require dirname(__DIR__).'/app/bootstrap.php';admin_required();$adminPage='dashboard';$adminTitle='داشبورد';$counts=['products'=>(int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(),'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'new_orders'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE order_status='new'")->fetchColumn(),'low_stock'=>(int)db()->query("SELECT COUNT(*) FROM products WHERE status='active' AND stock<=3")->fetchColumn(),'customers'=>(int)db()->query('SELECT COUNT(*) FROM customers')->fetchColumn(),'sms_failed'=>(int)db()->query("SELECT COUNT(*) FROM sms_logs WHERE status='failed' AND created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)")->fetchColumn(),'festivals'=>(function():int{$stmt=db()->prepare("SELECT COUNT(*) FROM festivals WHERE is_active=1 AND starts_at<=? AND ends_at>=?");$now=date('Y-m-d H:i:s');$stmt->execute([$now,$now]);return (int)$stmt->fetchColumn();})()];$recent=db()->query('SELECT id,order_number,customer_name,phone,total,order_status,created_at FROM orders ORDER BY id DESC LIMIT 8')->fetchAll();require __DIR__.'/partials/header.php';?><div class="admin-title"><h1>وضعیت فروشگاه</h1><a class="btn btn-primary" href="<?=e(app_url('admin/product-quick-add.php'))?>">+ افزودن سریع محصول</a></div><div class="stats"><div class="card stat"><strong><?=fa_number($counts['products'])?></strong><span>محصول</span></div><div class="card stat"><strong><?=fa_number($counts['orders'])?></strong><span>کل سفارش‌ها</span></div><div class="card stat"><strong><?=fa_number($counts['new_orders'])?></strong><span>سفارش جدید</span></div><div class="card stat"><strong><?=fa_number($counts['low_stock'])?></strong><span>موجودی کم</span></div><div class="card stat"><strong><?=fa_number($counts['festivals'])?></strong><span>جشنواره فعال</span></div><div class="card stat"><strong><?=fa_number($counts['customers'])?></strong><span>مشتری</span></div><div class="card stat"><strong><?=fa_number($counts['sms_failed'])?></strong><span>خطای پیامک ۷ روز</span></div></div><div class="admin-title"><h2>آخرین سفارش‌ها</h2><a href="<?=e(app_url('admin/orders.php'))?>">مشاهده همه</a></div><div class="table-wrap"><table><thead><tr><th>شماره</th><th>مشتری</th><th>مبلغ</th><th>وضعیت</th><th>تاریخ</th></tr></thead><tbody><?php foreach($recent as $o):?><tr><td><a href="<?=e(app_url('admin/order.php?id='.$o['id']))?>"><?=e($o['order_number'])?></a></td><td><?=e($o['customer_name'])?><br><small><?=e($o['phone'])?></small></td><td><?=fa_number(format_price($o['total']))?> تومان</td><td><span class="badge"><?=e($o['order_status'])?></span></td><td><?=e(jalali_format($o['created_at']))?></td></tr><?php endforeach?><?php if(!$recent):?><tr><td colspan="5">هنوز سفارشی ثبت نشده است.</td></tr><?php endif?></tbody></table></div><?php require __DIR__.'/partials/footer.php';
